package edu.eci.dosw.campusseguro.identity.identity_service.exception;

import java.util.Arrays;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

/**
 * Catalog of statuses and error codes of the Integration Standards (section 7.2) that MS01 can return in the
 * ErrorResponse, each code knows its HTTP status, its catalog text and a generic and safe message in Spanish that is
 * used when the error is generated by the framework and not by a business rule
 *
 * For each HTTP status the first declared code is the general one, the one used when only the status is known
 */
public enum ErrorCode {

    VALIDATION(400, "VALIDACION", Messages.INVALID_DATA),
    INVALID_CODE(400, "CODIGO_INVALIDO", Messages.INVALID_DATA),
    UNAUTHENTICATED(401, "NO_AUTENTICADO", Messages.UNAUTHENTICATED),
    BAD_CREDENTIALS(401, "CREDENCIALES_INCORRECTAS", Messages.UNAUTHENTICATED),
    FORBIDDEN(403, "PROHIBIDO", Messages.FORBIDDEN),
    INACTIVE_ACCOUNT(403, "CUENTA_INACTIVA", Messages.FORBIDDEN),
    NOT_FOUND(404, "NO_ENCONTRADO", "Recurso no encontrado."),
    METHOD_NOT_ALLOWED(405, "METODO_NO_PERMITIDO", "Método HTTP no permitido."),
    CONFLICT(409, "CONFLICTO", "Conflicto con el estado actual del recurso."),
    UNSUPPORTED_MEDIA_TYPE(415, "TIPO_NO_SOPORTADO", "Tipo de contenido no soportado."),
    BUSINESS_RULE(422, "REGLA_NEGOCIO", "La operación no cumple una regla de negocio."),
    INTERNAL_ERROR(500, "ERROR_INTERNO", "Error interno del servidor.");

    private static final Map<Integer, ErrorCode> GENERAL_BY_STATUS = Arrays.stream(values())
            .collect(Collectors.toUnmodifiableMap(
                    ErrorCode::getStatus,
                    Function.identity(),
                    (general, other) -> general));

    private final int status;
    private final String code;
    private final String message;

        /**
     * Creates a code of the catalog
     *
     * @param status HTTP status with which the response is given
     * @param code text of the codigo field of the ErrorResponse
     * @param message generic and safe message in Spanish
     */
    ErrorCode(int status, String code, String message) {
        this.status = status;
        this.code = code;
        this.message = message;
    }

        /**
     * Gets the HTTP status of the code
     *
     * @return the HTTP status with which the response is given
     */
    public int getStatus() {
        return status;
    }

        /**
     * Gets the text of the codigo field of the ErrorResponse
     *
     * @return the code of the catalog in UPPERCASE_WITH_UNDERSCORE
     */
    public String getCode() {
        return code;
    }

        /**
     * Gets the generic and safe message of the code
     *
     * @return the generic message in Spanish
     */
    public String getMessage() {
        return message;
    }

        /**
     * Returns the general code that corresponds to an HTTP status, the 4xx statuses that the catalog does not
     * contemplate are treated as VALIDATION and the 5xx as INTERNAL_ERROR
     *
     * @param status HTTP status of the response
     * @return the general code of the status
     */
    public static ErrorCode forStatus(int status) {
        ErrorCode general = GENERAL_BY_STATUS.get(status);
        if (general != null) {
            return general;
        }
        if (status >= INTERNAL_ERROR.status) {
            return INTERNAL_ERROR;
        }
        return VALIDATION;
    }

        /**
     * Messages shared by several codes of the catalog
     */
    private static final class Messages {

        static final String INVALID_DATA = "Datos inválidos.";
        static final String UNAUTHENTICATED = "No autenticado.";
        static final String FORBIDDEN = "No cuenta con los permisos suficientes para realizar esta operación.";

                /**
         * Utility class, it is not instantiated
         */
        private Messages() {
        }
    }
}
